"""Original SVG concept illustrations. No third-party imagery or fonts."""
from pathlib import Path
R=Path(__file__).resolve().parents[1]/'assets'
DEFS='''<defs><linearGradient id="metal" x2=".8" y2="1"><stop stop-color="#fafbff"/><stop offset=".4" stop-color="#b7c1d3"/><stop offset=".8" stop-color="#e1e6ee"/><stop offset="1" stop-color="#8c9cb4"/></linearGradient><linearGradient id="screen" x2="1" y2="1"><stop stop-color="#152555"/><stop offset=".5" stop-color="#687ff2"/><stop offset="1" stop-color="#dbb9ef"/></linearGradient><linearGradient id="glass" x2=".9" y2="1"><stop stop-color="#d3d9f3"/><stop offset=".45" stop-color="#9faef2"/><stop offset="1" stop-color="#353975"/></linearGradient><radialGradient id="glow"><stop stop-color="#d8d9ff"/><stop offset="1" stop-color="#a8b6ee" stop-opacity="0"/></radialGradient><filter id="shadow" x="-.4" y="-.4" width="1.8" height="2"><feDropShadow dx="0" dy="24" stdDeviation="20" flood-color="#15203a" flood-opacity=".22"/></filter></defs>'''
def svg(body,w=600,h=440):return f'<svg xmlns="http://www.w3.org/2000/svg" width="{w}" height="{h}" viewBox="0 0 {w} {h}">{DEFS}{body}</svg>'
LAPTOP='''<g filter="url(#shadow)"><rect x="95" y="55" width="410" height="275" rx="16" fill="url(#metal)"/><rect x="106" y="66" width="388" height="250" rx="9" fill="#101522"/><rect x="115" y="75" width="370" height="232" rx="3" fill="url(#screen)"/><path d="M115 284Q230 70 485 160V305H115Z" fill="#a0c7fa" opacity=".5"/><path d="M115 306Q310 110 485 135V306" fill="#b8a8f3" opacity=".65"/><path d="M95 330 35 367Q30 379 53 382H546Q570 379 564 367L505 330Z" fill="url(#metal)"/><path d="M35 367H565" stroke="#8895aa" stroke-width="3"/><path d="M235 330H365L358 340H243Z" fill="#96a4bb"/></g>'''
AUDIO='''<g filter="url(#shadow)"><path d="M156 250V186a144 144 0 0 1 288 0v64" fill="none" stroke="#9aa7bd" stroke-width="48"/><path d="M156 250V186a144 144 0 0 1 288 0v64" fill="none" stroke="url(#metal)" stroke-width="32"/><rect x="121" y="204" width="103" height="170" rx="46" transform="rotate(-12 175 290)" fill="url(#metal)"/><rect x="376" y="204" width="103" height="170" rx="46" transform="rotate(12 425 290)" fill="url(#metal)"/><rect x="151" y="218" width="57" height="141" rx="28" transform="rotate(-12 175 290)" fill="#687a96"/><rect x="392" y="218" width="57" height="141" rx="28" transform="rotate(12 425 290)" fill="#687a96"/></g>'''
WATCH='''<g transform="rotate(-20 300 220)" filter="url(#shadow)"><rect x="246" y="0" width="108" height="440" rx="46" fill="#c4c9d9"/><path d="M270 40v90m58-90v90m-58 180v90m58-90v90" stroke="#a6afc3" stroke-width="3"/><rect x="203" y="119" width="194" height="206" rx="49" fill="url(#metal)"/><rect x="216" y="132" width="168" height="180" rx="39" fill="#101727"/><circle cx="300" cy="222" r="61" fill="none" stroke="#829aff" stroke-width="12"/><path d="M300 171v51l32 20" fill="none" stroke="#e4eaff" stroke-width="7" stroke-linecap="round"/><rect x="397" y="170" width="13" height="40" rx="6" fill="#b4bfd1"/></g>'''
DISPLAY='''<g filter="url(#shadow)"><path d="M281 310h38l8 62h-54Z" fill="url(#metal)"/><ellipse cx="300" cy="377" rx="83" ry="9" fill="url(#metal)"/><rect x="55" y="42" width="490" height="286" rx="14" fill="url(#metal)"/><rect x="66" y="53" width="468" height="262" rx="6" fill="url(#screen)"/><path d="M66 250Q250 50 534 150V315H66Z" fill="#ccd9fa" opacity=".5"/><path d="M66 290Q290 120 534 240V315H66Z" fill="#c3a6e8" opacity=".6"/></g>'''
for name,body in [('laptop',LAPTOP),('audio',AUDIO),('watch',WATCH),('display',DISPLAY),('1',LAPTOP),('2',AUDIO),('3',WATCH)]:
 (R/f'object-{name}.svg').write_text(svg(body))
hero='''<rect width="1600" height="800" fill="#edf0f6"/><ellipse cx="1160" cy="350" rx="520" ry="430" fill="url(#glow)"/><path d="M720 790 1600 545V800H720" fill="#e0e5f0"/><g transform="translate(750 240) rotate(-8 300 220) scale(1.15)">'''+LAPTOP+'''</g><g transform="translate(1200 0) scale(.55)">'''+AUDIO+'''</g><circle cx="1350" cy="620" r="68" fill="#c5c9ed" opacity=".5"/>'''
(R/'hero-zadra.svg').write_text(svg(hero,1600,800))
(R/'editorial-1.svg').write_text(svg('<ellipse cx="400" cy="530" rx="380" ry="300" fill="#1e2744"/><g transform="translate(80 300) rotate(-18 300 220) scale(1.05)">'+AUDIO+'</g>',800,750))
(R/'editorial-2.svg').write_text(svg('<rect width="800" height="750" fill="#e9eaf2"/><circle cx="600" cy="470" r="350" fill="#e0e0f4"/><g transform="translate(80 250) rotate(8 300 220)">'+DISPLAY+'</g>',800,750))
print('11 original vector assets generated')
